class Solution {
public:
    vector<int> platesBetweenCandles(string s, vector<vector<int>>& queries) {
        int n = s.size();
        vector<int> prevCandle(n), nextCandle(n), prefix(n + 1, 0);

        int last = -1;
        for (int i = 0; i < n; i++) {
            if (s[i] == '|') last = i;
            prevCandle[i] = last;
        }

        last = -1;
        for (int i = n - 1; i >= 0; i--) {
            if (s[i] == '|') last = i;
            nextCandle[i] = last;
        }

        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + (s[i] == '*' ? 1 : 0);
        }

        vector<int> ans;
        ans.reserve(queries.size());
        for (auto& q : queries) {
            int l = q[0], r = q[1];
            int leftCandle = nextCandle[l];
            int rightCandle = prevCandle[r];
            if (leftCandle == -1 || rightCandle == -1 || leftCandle >= rightCandle) {
                ans.push_back(0);
            } else {
                ans.push_back(prefix[rightCandle] - prefix[leftCandle]);
            }
        }
        return ans;
    }
};
